async def process(conn, session_id, revision_id, domain):
    async def fetch_rows(txn):
        versioned_read_async = getattr(txn, "versioned_read_async", None)
        if callable(versioned_read_async):
            async with versioned_read_async(domain, revision_id) as scoped_txn:
                return await scoped_txn.query(Model).execute_async()
        return []

    return await conn.session(session_id).read_async(fn=fetch_rows)

